use super::fem_mesh_config::{FemMeshConfig, FemSourceModel};
use super::shifted_laplacian_shift::ShiftedLaplacianShift;
use anyhow::Result;
use sonium_xem::{CrossoverFilter, Directivity, Point3D, RoomGeometry, RoomSimulation};

pub(super) fn validate_mesh_config(mesh_config: &FemMeshConfig) -> Result<()> {
    anyhow::ensure!(
        mesh_config.elements_per_wavelength.is_finite()
            && mesh_config.elements_per_wavelength >= 2.0,
        "elements_per_wavelength must be finite and at least two"
    );
    anyhow::ensure!(
        mesh_config.grading_factor.is_finite() && mesh_config.grading_factor >= 1.0,
        "grading_factor must be finite and at least one"
    );
    anyhow::ensure!(
        mesh_config.fine_radius.is_finite() && mesh_config.fine_radius >= 0.0,
        "fine_radius must be finite and non-negative"
    );
    if let FemSourceModel::Gaussian { sigma } = mesh_config.source_model {
        anyhow::ensure!(
            sigma.is_finite() && sigma > 0.0,
            "Gaussian source sigma must be finite and positive"
        );
    }
    anyhow::ensure!(
        mesh_config.gmres_tolerance.is_finite() && mesh_config.gmres_tolerance > 0.0,
        "gmres_tolerance must be finite and positive"
    );
    anyhow::ensure!(
        mesh_config.gmres_restart > 0,
        "gmres_restart must be positive"
    );
    anyhow::ensure!(
        mesh_config.rebuild_precond_every > 0,
        "rebuild_precond_every must be positive"
    );
    anyhow::ensure!(
        mesh_config.modal_damping_ratio.is_finite() && mesh_config.modal_damping_ratio >= 0.0,
        "modal_damping_ratio must be a finite non-negative value"
    );
    if let ShiftedLaplacianShift::K2 { alpha, beta } | ShiftedLaplacianShift::Csl { alpha, beta } =
        mesh_config.shifted_laplacian_shift
    {
        anyhow::ensure!(
            alpha.is_finite() && alpha >= 0.0 && beta.is_finite() && beta >= 0.0,
            "shifted_laplacian_shift k2 alpha/beta must be finite non-negative values"
        );
    }
    Ok(())
}

/// Validate that every source and listening position is strictly inside the
/// actual room footprint. Catches scenario authoring bugs before they manifest as silent
/// zero pressure fields (sources outside the mesh contribute nothing to the
/// RHS) or hard-to-diagnose interpolation fallbacks.
pub(super) fn validate_geometry(simulation: &RoomSimulation) -> Result<()> {
    anyhow::ensure!(
        !simulation.frequencies.is_empty(),
        "FEM frequency grid must contain at least one frequency"
    );
    anyhow::ensure!(
        simulation
            .frequencies
            .iter()
            .all(|frequency| frequency.is_finite() && *frequency > 0.0),
        "FEM frequency grid must contain finite positive frequencies"
    );
    anyhow::ensure!(
        simulation
            .frequencies
            .windows(2)
            .all(|window| window[1] > window[0]),
        "FEM frequency grid must be strictly increasing"
    );
    let (width, depth, height) = simulation.room.dimensions();
    let check = |label: &str, idx: usize, name: &str, p: Point3D| -> Result<()> {
        let inside_footprint = match &simulation.room {
            RoomGeometry::Rectangular(_) => true,
            RoomGeometry::LShaped(room) => {
                (p.y < room.depth1 && p.x < room.width1)
                    || (p.y >= room.depth1 && p.x < room.width2)
            }
        };
        anyhow::ensure!(
            p.x > 0.0
                && p.x < width
                && p.y > 0.0
                && p.y < depth
                && p.z > 0.0
                && p.z < height
                && inside_footprint,
            "{label} {idx} ('{name}') at ({:.3}, {:.3}, {:.3}) is outside the room \
             footprint [0, {:.3}] × [0, {:.3}] × [0, {:.3}]",
            p.x,
            p.y,
            p.z,
            width,
            depth,
            height,
        );
        Ok(())
    };
    for (i, src) in simulation.sources.iter().enumerate() {
        check("source", i, &src.name, src.position)?;
        anyhow::ensure!(
            !src.name.trim().is_empty(),
            "source {i} ('{}') must have a non-empty name",
            src.name
        );
        anyhow::ensure!(
            src.amplitude.is_finite(),
            "source {i} ('{}') amplitude must be finite",
            src.name
        );
        let orientation_norm = src.orientation.length();
        anyhow::ensure!(
            src.orientation.x.is_finite()
                && src.orientation.y.is_finite()
                && src.orientation.z.is_finite()
                && orientation_norm.is_finite()
                && orientation_norm > 1.0e-10,
            "source {i} ('{}') orientation must be finite and non-zero",
            src.name
        );
        for &frequency in &simulation.frequencies {
            for (target_index, target) in simulation
                .listening_positions
                .iter()
                .chain(std::iter::once(&src.position))
                .enumerate()
            {
                src.try_amplitude_towards(target, frequency)
                    .map_err(|error| {
                        anyhow::anyhow!(
                            "source {i} ('{}') directivity/crossover invalid at {frequency:.3} Hz for target {target_index}: {error}",
                            src.name
                        )
                    })?;
            }
            let complex_amplitude = src.complex_isotropic_amplitude(frequency);
            anyhow::ensure!(
                complex_amplitude.re.is_finite() && complex_amplitude.im.is_finite(),
                "source {i} ('{}') complex crossover amplitude is non-finite at {frequency:.3} Hz",
                src.name
            );
        }
    }
    for (i, lp) in simulation.listening_positions.iter().enumerate() {
        check("listening position", i, "lp", *lp)?;
    }
    Ok(())
}

/// Enforce ownership of speaker crossover response at the FEM boundary.
///
/// A complex directivity grid is the handoff format for a measured/BEM
/// loudspeaker response and normally already contains crossover magnitude and
/// phase. Applying a room-side filter a second time is therefore rejected
/// unless the caller explicitly opts into intentional chained filtering in
/// [`FemMeshConfig`].
pub fn validate_source_signal_ownership(
    simulation: &RoomSimulation,
    mesh_config: &FemMeshConfig,
) -> Result<()> {
    for (index, source) in simulation.sources.iter().enumerate() {
        if matches!(source.directivity, Directivity::ComplexGrid(_))
            && !matches!(source.crossover, CrossoverFilter::FullRange)
            && !mesh_config.allow_chained_complex_crossover
        {
            anyhow::bail!(
                "source {index} ('{}') uses a complex directivity grid with a non-full-range crossover; set allow_chained_complex_crossover=true only for intentional chained filtering",
                source.name
            );
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use num_complex::Complex64;
    use sonium_compute::HostMatrix;
    use sonium_xem::{
        CrossoverFilter, Directivity, LShapedRoom, RoomGeometry, RoomSimulation, Source,
    };

    #[test]
    fn l_shaped_cutout_is_not_valid_room_volume() {
        let room = LShapedRoom::new(4.0, 3.0, 2.0, 2.0, 2.5);
        let simulation = RoomSimulation::new(
            RoomGeometry::LShaped(room),
            vec![Source::omnidirectional(Point3D::new(3.0, 4.0, 1.0), 1.0)],
            vec![Point3D::new(1.0, 4.0, 1.0)],
        );

        let error = validate_geometry(&simulation).unwrap_err().to_string();
        assert!(error.contains("outside the room footprint"));
    }

    #[test]
    fn rectangular_source_outside_is_rejected_before_rhs_assembly() {
        let simulation = RoomSimulation::new(
            RoomGeometry::Rectangular(sonium_xem::RectangularRoom::new(4.0, 3.0, 2.0)),
            vec![Source::omnidirectional(Point3D::new(4.0, 1.0, 1.0), 1.0)],
            vec![Point3D::new(1.0, 1.0, 1.0)],
        );

        let error = validate_geometry(&simulation).unwrap_err().to_string();
        assert!(error.contains("source 0"));
        assert!(error.contains("outside the room footprint"));
    }

    fn valid_simulation() -> RoomSimulation {
        RoomSimulation::new(
            RoomGeometry::Rectangular(sonium_xem::RectangularRoom::new(4.0, 3.0, 2.0)),
            vec![Source::omnidirectional(Point3D::new(1.0, 1.0, 1.0), 1.0)],
            vec![Point3D::new(2.0, 1.0, 1.0)],
        )
    }

    #[test]
    fn empty_frequency_grid_is_rejected() {
        let mut simulation = valid_simulation();
        simulation.frequencies.clear();

        let error = validate_geometry(&simulation).unwrap_err().to_string();
        assert!(error.contains("frequency grid"));
    }

    #[test]
    fn invalid_frequency_grid_is_rejected() {
        let mut simulation = valid_simulation();
        simulation.frequencies = vec![400.0, 400.0];

        let error = validate_geometry(&simulation).unwrap_err().to_string();
        assert!(error.contains("strictly increasing"));
    }

    #[test]
    fn non_finite_frequency_is_rejected() {
        let mut simulation = valid_simulation();
        simulation.frequencies = vec![f64::NAN];

        let error = validate_geometry(&simulation).unwrap_err().to_string();
        assert!(error.contains("finite positive"));
    }

    #[test]
    fn non_finite_source_amplitude_is_rejected() {
        let mut simulation = valid_simulation();
        simulation.sources[0].amplitude = f64::NAN;

        let error = validate_geometry(&simulation).unwrap_err().to_string();
        assert!(error.contains("amplitude must be finite"));
    }

    #[test]
    fn blank_source_name_is_rejected() {
        let mut simulation = valid_simulation();
        simulation.sources[0].name.clear();

        let error = validate_geometry(&simulation).unwrap_err().to_string();
        assert!(error.contains("non-empty name"));
    }

    #[test]
    fn zero_source_orientation_is_rejected() {
        let mut simulation = valid_simulation();
        simulation.sources[0].orientation = Point3D::new(0.0, 0.0, 0.0);

        let error = validate_geometry(&simulation).unwrap_err().to_string();
        assert!(error.contains("orientation must be finite and non-zero"));
    }

    #[test]
    fn invalid_mesh_refinement_controls_are_rejected() {
        let mut config = FemMeshConfig::default();
        config.grading_factor = f64::NAN;
        assert!(
            validate_mesh_config(&config)
                .unwrap_err()
                .to_string()
                .contains("grading_factor")
        );

        let mut config = FemMeshConfig::default();
        config.fine_radius = -1.0;
        assert!(
            validate_mesh_config(&config)
                .unwrap_err()
                .to_string()
                .contains("fine_radius")
        );

        for sigma in [0.0, -0.1, f64::NAN, f64::INFINITY] {
            let mut config = FemMeshConfig::default();
            config.source_model = super::super::fem_mesh_config::FemSourceModel::Gaussian { sigma };
            let error = validate_mesh_config(&config).unwrap_err().to_string();
            assert!(
                error.contains("Gaussian source sigma"),
                "{sigma:?}: {error}"
            );
        }

        let mut gaussian = FemMeshConfig::default();
        gaussian.source_model =
            super::super::fem_mesh_config::FemSourceModel::Gaussian { sigma: 0.07 };
        assert!(validate_mesh_config(&gaussian).is_ok());

        for tolerance in [0.0, -1.0e-6, f64::NAN, f64::INFINITY] {
            let mut config = FemMeshConfig::default();
            config.gmres_tolerance = tolerance;
            let error = validate_mesh_config(&config).unwrap_err().to_string();
            assert!(error.contains("gmres_tolerance"), "{tolerance:?}: {error}");
        }

        let mut config = FemMeshConfig::default();
        config.gmres_restart = 0;
        assert!(
            validate_mesh_config(&config)
                .unwrap_err()
                .to_string()
                .contains("gmres_restart")
        );

        let mut config = FemMeshConfig::default();
        config.rebuild_precond_every = 0;
        assert!(
            validate_mesh_config(&config)
                .unwrap_err()
                .to_string()
                .contains("rebuild_precond_every")
        );
    }

    fn complex_grid_source() -> Source {
        let grid = sonium_xem::ComplexDirectivityGrid::try_new(
            vec![0.0, 90.0, 180.0, 270.0],
            vec![0.0, 90.0, 180.0],
            vec![500.0],
            vec![HostMatrix::from_elem(3, 4, Complex64::new(1.0, 0.0))],
        )
        .unwrap();
        Source::new(
            Point3D::new(1.0, 1.0, 1.0),
            Directivity::ComplexGrid(grid),
            1.0,
        )
        .with_crossover(CrossoverFilter::Lowpass {
            cutoff_freq: 500.0,
            order: 2,
        })
    }

    #[test]
    fn complex_grid_crossover_chaining_requires_explicit_opt_in() {
        let mut simulation = valid_simulation();
        simulation.sources[0] = complex_grid_source();
        let config = FemMeshConfig::default();
        let error = validate_source_signal_ownership(&simulation, &config).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("allow_chained_complex_crossover")
        );

        let mut chained = config;
        chained.allow_chained_complex_crossover = true;
        validate_source_signal_ownership(&simulation, &chained).unwrap();
    }

    #[test]
    fn complex_grid_with_full_range_crossover_is_unconditionally_allowed() {
        let mut simulation = valid_simulation();
        let mut source = complex_grid_source();
        source.crossover = CrossoverFilter::FullRange;
        simulation.sources[0] = source;
        validate_source_signal_ownership(&simulation, &FemMeshConfig::default()).unwrap();
    }
}
